func inspect_question(q: Question) -> void:
	# Tutte le domande possiedono la proprietà text
	print("Testo: ", q.text)

	if q is NumericQuestion:
		# Usiamo 'as' per dire all'editor che qui vogliamo trattarlo come NumericQuestion
		var num_q: NumericQuestion = q as NumericQuestion
		print("Tipo numerico. Bersaglio: ", num_q.target_value, " Tolleranza: ", num_q.tolerance)
	elif q is TrueFalseQuestion:
		print("Tipo Vero/Falso. Mostra 2 pulsanti.")
	else:
		print("Tipo standard a scelta multipla. Opzioni: ", q.options.size())
